      "code": "import pytest
from hypothesis import given, settings, strategies as st
import impl


@given(
    flag_key=st.text(min_size=1, max_size=10, alphabet=st.characters(whitelist_categories=('L', 'N'))),
    user_id=st.text(min_size=1, max_size=10, alphabet=st.characters(whitelist_categories=('L', 'N'))),
    p_low=st.integers(min_value=0, max_value=100),
    p_high=st.integers(min_value=0, max_value=100),
)
@settings(max_examples=100)
def test_monotonic_inclusion_across_percentages(flag_key, user_id, p_low, p_high):
    if p_low > p_high:
        p_low, p_high = p_high, p_low
    enabled_low = impl.is_enabled(flag_key, user_id, p_low)
    enabled_high = impl.is_enabled(flag_key, user_id, p_high)
    if enabled_low:
        assert enabled_high, (
            f"user enabled at percentage={p_low} became disabled at higher percentage={p_high} "
            f"for flag_key={flag_key!r}, user_id={user_id!r}"
        )
"
    }
  ]
}
